                    </div>
                </div>

                <!-- Font Size -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title">Font Size</h5>
                        @foreach (var option in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{option}")" value="@option"
                                       checked="@(fontSize == option)"
                                       @onchange="() => fontSize = option" />
                                <label class="form-check-label" for="@($"fs-{option}")">@option</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title">Language</h5>
                        <select class="form-select" @bind="language">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                        </select>
                    </div>
                </div>

                <!-- Compact Mode -->
                <div class="card mb-4">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                            <label class="form-check-label" for="compactMode">
                                <strong>Compact Mode</strong>
                                <br />
                                <small class="text-muted">Reduce spacing and padding throughout the UI</small>
                            </label>
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
