toolArgs.file_text:
@inject ISettingsService SettingsService

<div class="p-4">
    <h3 class="mb-4">Appearance</h3>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center py-5">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading…</span>
            </div>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title">Theme</h5>
                        @foreach (var option in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{option}")" value="@option"
                                       checked="@(theme == option)"
                                       @onchange="() => theme = option" />
                                <label class="form-check-label" for="@($"theme-{option}")">@option</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title">Font Size</h5>
                        @foreach (var option in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{option}")" value="@option"
                                       checked="@(fontSize == option)"
                                       @onchange="() => fontSize = option" />
                                <label class="form-check-label" for="@($"fs-{option}")">@option</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title">Language</h5>
                        <select class="form-select" @bind="language">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                        </select>
                    </div>
                </div>

                <!-- Compact Mode -->
                <div class="card mb-4">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                            <label class="form-check-label" for="compactMode">
                                <strong>Compact Mode</strong>
                                <br />
                                <small class="text-muted">Reduce spacing and padding throughout the UI</small>
                            </label>
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @if (isSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card sticky-top" style="top: 1rem;">
                    <div class="card-header">
                        <h5 class="mb-0">Preview</h5>
                    </div>
                    <div class="card-body @PreviewBackgroundClass" style="@PreviewStyle min-height: 280px; transition: all 0.3s;">
                        <h6 style="@PreviewTextStyle" class="@PreviewTextClass">Sample Heading</h6>
                        <p style="@PreviewTextStyle" class="@PreviewTextClass @(compactMode ? "mb-1" : "mb-3")">
                            This is how your content will look with the selected appearance settings.
                        </p>
                        <div class="d-flex gap-2 @(compactMode ? "mb-1" : "mb-3")">
                            <button class="btn btn-sm btn-primary">Primary</button>
                            <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                        </div>
                        <ul class="list-group list-group-flush" style="@PreviewTextStyle">
                            <li class="list-group-item @PreviewListItemClass" style="@PreviewItemStyle @(compactMode ? "padding: 0.25rem 0.5rem;" : "")">Item One</li>
                            <li class="list-group-item @PreviewListItemClass" style="@PreviewItemStyle @(compactMode ? "padding: 0.25rem 0.5rem;" : "")">Item Two</li>
                            <li class="list-group-item @PreviewListItemClass" style="@PreviewItemStyle @(compactMode ? "padding: 0.25rem 0.5rem;" : "")">Item Three</li>
                        </ul>
                        <div class="mt-2">
                            <span class="badge bg-secondary">@LanguageDisplayName</span>
                            <span class="badge bg-info">@theme Theme</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;

    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            theme = settings.Theme;
            fontSize = settings.FontSize;
            language = settings.Language;
            compactMode = settings.CompactMode;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            statusMessage = "Appearance settings saved!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private string PreviewFontSize => fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewStyle => theme == "Dark"
        ? $"background-color: #1e1e1e; color: #e0e0e0; font-size: {PreviewFontSize};"
        : $"font-size: {PreviewFontSize};";

    private string PreviewBackgroundClass => theme == "Dark" ? "text-light" : "";

    private string PreviewTextStyle => $"font-size: {PreviewFontSize};";

    private string PreviewTextClass => theme == "Dark" ? "text-light" : "";

    private string PreviewListItemClass => theme == "Dark" ? "bg-dark text-light border-secondary" : "";

    private string PreviewItemStyle => $"font-size: {PreviewFontSize};";

    private string LanguageDisplayName => language switch
    {
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => "English"
    };
}

